Linksrotation um x:

  x                  y
 / \                / \
A   y      ->      x   C
   / \            / \
  B   C          A   B

static Knoten RotiereLinks(Knoten x)
{
    Knoten y = x.Rechts!;
    x.Rechts = y.Links; // B wandert
    y.Links = x;
    return y;           // neue Wurzel
}

var punkte = new SortedSet<int>
    { 42, 17, 88, 17, 63 };
Console.WriteLine(string.Join(" ", punkte));
Console.WriteLine(
    $"{punkte.Min} {punkte.Max}");
var mitte = punkte.GetViewBetween(40, 70);
Console.WriteLine(string.Join(" ", mitte));

var noten =
    new SortedDictionary<string, int>();
noten["Mayer"] = 2;
noten["Huber"] = 1;
noten["Bauer"] = 3;
foreach (var e in noten)
    Console.WriteLine(
        $"{e.Key}: {e.Value}");
// Ausgabe:
// 17 42 63 88
// 17 88
// 42 63
// Bauer: 3
// Huber: 1
// Mayer: 2

